  const [hra, setHra] = reactExports.useState("120000");
  const [section80C, setSection80C] = reactExports.useState("150000");
  const [section80D, setSection80D] = reactExports.useState("25000");
  const [otherDeductions, setOtherDeductions] = reactExports.useState("50000");
